def process_cmdline(pid):
    try:
        raw = Path('/proc') / str(pid) / 'cmdline'
        return raw.read_bytes().replace(b'\x00', b' ').decode('utf-8', 'replace').strip()
    except Exception:
        return ''

def process_cwd(pid):
    try:
        return os.readlink(f'/proc/{pid}/cwd')
    except Exception:
        return ''

