parent_pid = os.getppid()
matching = []
for name in os.listdir('/proc'):
    if not name.isdigit():
        continue
    pid = int(name)
    if pid in {self_pid, parent_pid}:
        continue
    cmd = process_cmdline(pid)
    cwd = process_cwd(pid)
    if not cmd:
        continue
    same_test = ('orchestrator.py' in cmd or 'pw_scale_mac_mobility_ha' in cmd or 'multi_mobility' in cmd)
    same_cwd = str(TEST_DIR) in cwd or str(TEST_DIR) in cmd
