# Normalize service matrix from whichever shape the local helper uses.
def obj_to_plain(o):
    if dataclasses.is_dataclass(o):
        return dataclasses.asdict(o)
    if isinstance(o, dict):
        return dict(o)
    if hasattr(o, '_asdict'):
        return dict(o._asdict())
    if hasattr(o, '__dict__'):
        return {k: v for k, v in vars(o).items() if not k.startswith('_')}
    return {'value': o}

def find_service_name(d, idx):
    preferred_keys = ['service_name', 'service', 'instance', 'evpn_instance', 'vpls_instance', 'bd_name', 'name']
    for k in preferred_keys:
        v = d.get(k)
        if isinstance(v, str) and v.strip():
            return v.strip()
    for v in d.values():
        if isinstance(v, str) and re.search(r'(EVPN|VPLS|PW|SI|BD|SERVICE|pw_scale)', v, re.I):
            return v.strip()
    # Last-resort names used only if the builder omitted a service label.
    return f'PW_SCALE_{idx:03d}'

def find_macs(d, idx):
    values = []
    def walk(x):
        if isinstance(x, str):
            values.extend(re.findall(r'(?i)\b[0-9a-f]{2}(?::[0-9a-f]{2}){5}\b', x))
        elif isinstance(x, dict):
            for vv in x.values(): walk(vv)
        elif isinstance(x, (list, tuple, set)):
            for vv in x: walk(vv)
    walk(d)
    values = [v.lower() for v in values]
    pe4 = next((m for m in values if m.startswith('00:de:ad:')), None)
    rr = next((m for m in values if m.startswith('00:de:be:')), None)
    if not pe4:
        pe4 = f'00:de:ad:01:{idx:02x}'
    if not rr:
        rr = f'00:de:be:01:{idx:02x}'
    return pe4.lower(), rr.lower()

