# Command helpers.
def call_run_show(device, commands):
    if isinstance(commands, str):
        commands = [commands]
    # Try the local helper signatures without assuming one exact form.
    attempts = [
        lambda: run_show_commands(device, commands),
        lambda: run_show_commands(device_name=device, commands=commands),
        lambda: run_show_commands(device, commands, timeout=120),
        lambda: run_show_commands(device_name=device, commands=commands, timeout=120),
    ]
    last = None
    for fn in attempts:
        try:
            out = fn()
            return normalize_command_outputs(commands, out)
        except TypeError as e:
            last = e
            continue
    raise last or RuntimeError('run_show_commands call failed')

def normalize_command_outputs(commands, out):
    if isinstance(out, dict):
        # Common shapes: {cmd: text}, {"outputs": {cmd: text}}, {"results": [...]}
        if all(cmd in out for cmd in commands):
            return {cmd: str(out.get(cmd, '')) for cmd in commands}
        for key in ['outputs', 'command_outputs']:
            if isinstance(out.get(key), dict):
                return {cmd: str(out[key].get(cmd, '')) for cmd in commands}
        for key in ['results', 'commands']:
            if isinstance(out.get(key), list):
                res = {}
                for i, item in enumerate(out[key]):
                    if isinstance(item, dict):
                        cmd = item.get('command') or item.get('cmd') or (commands[i] if i < len(commands) else str(i))
                        txt = item.get('output') or item.get('stdout') or item.get('text') or item.get('result') or ''
                        res[str(cmd)] = str(txt)
                if res:
                    return {cmd: res.get(cmd, '') for cmd in commands}
        if len(commands) == 1:
            return {commands[0]: json.dumps(out)}
    if isinstance(out, list):
        res = {}
        for i, item in enumerate(out):
            cmd = commands[i] if i < len(commands) else str(i)
            if isinstance(item, dict):
                txt = item.get('output') or item.get('stdout') or item.get('text') or item.get('result') or json.dumps(item)
            else:
                txt = str(item)
            res[cmd] = txt
        return {cmd: res.get(cmd, '') for cmd in commands}
    if len(commands) == 1:
        return {commands[0]: str(out)}
    # Last-resort split is intentionally conservative.
    return {cmd: str(out) for cmd in commands}

