# Parsers.
def extract_first(patterns, text, flags=re.I):
    for pat in patterns:
        m = re.search(pat, text, flags)
        if m:
            return m.group(1).strip()
    return None

def parse_protocol(text):
    t = text or ''
    explicit = extract_first([
        r'\bProtocol\s*[:=]\s*([^\n\r|]+)',
        r'\bSource\s*[:=]\s*([^\n\r|]+)',
        r'\bType\s*[:=]\s*([^\n\r|]+)',
    ], t)
    if explicit:
        return explicit.split()[0]
    if re.search(r'\b(Local|L>)\b', t, re.I):
        return 'Local'
    if re.search(r'\b(VPLS|PW|v>)\b', t, re.I):
        return 'VPLS/PW'
    return None

def protocol_class(proto, text):
    blob = f'{proto or ""}\n{text or ""}'
    if re.search(r'\b(Local|L>)\b', blob, re.I):
        return 'local'
    if re.search(r'\b(VPLS|PW|v>)\b', blob, re.I):
        return 'pw'
    return 'unknown'

def parse_interface(text):
    t = text or ''
    v = extract_first([
        r'\bInterface\s*[:=]\s*([^\n\r|]+)',
        r'\bSource\s+Interface\s*[:=]\s*([^\n\r|]+)',
        r'\bPort\s*[:=]\s*([^\n\r|]+)',
        r'\bNexthop\s*[:=]\s*([^\n\r|]+)',
    ], t)
    if v:
        return v.split()[0]
    m = re.search(r'\b((?:ge|bundle|pw|vpls|lag|ae)[A-Za-z0-9_./:-]+)\b', t, re.I)
    return m.group(1) if m else None

def parse_sequence(text):
    nums = []
    for pat in [
        r'(?i)\b(?:mobility\s+)?seq(?:uence)?(?:\s+number)?\s*[:=]\s*(\d+)',
        r'(?i)\bseq\s+(\d+)\b',
    ]:
        nums.extend(int(x) for x in re.findall(pat, text or ''))
    return max(nums) if nums else None

def parse_suppression(text):
    t = text or ''
    if re.search(r'(?i)\b(suppression|suppressed|suppress)\b', t):
        if re.search(r'(?i)\b(no|not|disabled|false|inactive)\b.{0,20}\b(suppression|suppressed|suppress)\b', t):
            return 'inactive'
        if re.search(r'(?i)\b(suppression|suppressed|suppress)\b.{0,30}\b(active|enabled|true|yes)\b', t):
            return 'active'
        return 'mentioned'
    return 'none'

def parse_traffic_handling(text):
    v = extract_first([
        r'(?i)\bTraffic\s+handling\s*[:=]\s*([^\n\r|]+)',
        r'(?i)\bForwarding\s+state\s*[:=]\s*([^\n\r|]+)',
        r'(?i)\bHandling\s*[:=]\s*([^\n\r|]+)',
    ], text or '')
    if v:
        return v.strip()
    if re.search(r'(?i)\b(non-forward|discard|drop|blackhole|blocked|blocking)\b', text or ''):
        return 'Non-Forward'
    if re.search(r'(?i)\bforward\b', text or ''):
        return 'Forward'
    return None

def parse_history(text):
    lines = [ln.rstrip() for ln in (text or '').splitlines() if ln.strip()]
    event_lines = [ln for ln in lines if re.search(r'(?i)seq|mobility|move|local|vpls|pw|suppress|forward', ln)]
    seqs = []
    for ln in event_lines:
        for x in re.findall(r'(?i)\bseq(?:uence)?(?:\s+number)?\s*[:=]?\s*(\d+)\b', ln):
            try: seqs.append(int(x))
            except Exception: pass
    regressions = []
    for i in range(1, len(seqs)):
        if seqs[i] < seqs[i-1]:
            regressions.append({'index': i, 'previous': seqs[i-1], 'current': seqs[i]})
    return {'last_events': event_lines[-10:], 'sequences': seqs, 'sequence_regressions': regressions}

def missing_output(text, mac):
    t = text or ''
    if not t.strip():
        return True
    if mac.lower() not in t.lower() and re.search(r'(?i)not found|empty|no entries|does not exist|unknown', t):
        return True
    return False

def parse_vpls_pw(text):
    t = text or ''
    installed = None
    for pat in [
        r'(?i)Installed\s*[:=]\s*(\d+)',
        r'(?i)(\d+)\s*/\s*(\d+)\s+(?:PWs?\s+)?(?:installed|up)',
        r'(?i)installed\s+(\d+)'
    ]:
        m = re.search(pat, t)
        if m:
            installed = int(m.group(1))
            break
    if installed is None:
        installed = len([ln for ln in t.splitlines() if re.search(r'(?i)\bInstalled\b', ln)])
    down_lines = [ln.strip() for ln in t.splitlines() if re.search(r'(?i)\b(down|blocking|not-installed|failed)\b', ln)]
    return {'installed_count': installed, 'down_signatures': down_lines[:50], 'raw_line_count': len(t.splitlines())}

def get_output_from_batched(raw, service, mac):
    if raw is None:
        return None
    key_variants = [
        (service, mac), f'{service}|{mac}', f'{service}:{mac}', mac, service,
    ]
    if isinstance(raw, dict):
        for k in key_variants:
            if k in raw:
                return raw[k]
        # Search nested dict/list values for the MAC.
        for v in raw.values():
            if isinstance(v, str) and mac.lower() in v.lower():
                return v
            if isinstance(v, dict):
                txt = json.dumps(v)
                if mac.lower() in txt.lower():
                    return txt
    if isinstance(raw, list):
        for item in raw:
            txt = item if isinstance(item, str) else json.dumps(item)
            if mac.lower() in txt.lower() and service.lower() in txt.lower():
                return txt
        for item in raw:
            txt = item if isinstance(item, str) else json.dumps(item)
            if mac.lower() in txt.lower():
                return txt
    return None

def build_mac_cmd(service, mac):
    return f'show evpn mac-table detail instance {service} mac {mac} | no-more'

def build_history_cmd(service, mac):
    # This syntax is used only for read-only evidence. If unsupported, the rejection is captured.
    return f'show evpn instance {service} mac-history mac {mac} | no-more'

def take_snapshot(label):
    print(f'[INFO] taking {label} snapshot')
    snap = {
        'label': label,
        'timestamp': _dt.datetime.now().isoformat(timespec='seconds'),
        'devices': {},
        'service_count': len(services),
    }
    for dev_key, device in DEVICE_ALIASES.items():
        print(f'[INFO] snapshot device={device}')
        mac_requests = []
        for s in services:
            mac_requests.append({'service': s['service'], 'mac': s['pe4_mac'], 'role': 'pe4_source'})
            mac_requests.append({'service': s['service'], 'mac': s['rr_mac'], 'role': 'rr_source'})
        batched = try_batched(device, mac_requests)
        # Build direct commands for missing batched outputs and all history evidence.
        mac_cmds = []
        hist_cmds = []
        for s in services:
            for mac in [s['pe4_mac'], s['rr_mac']]:
                if get_output_from_batched(batched, s['service'], mac) is None:
                    mac_cmds.append(build_mac_cmd(s['service'], mac))
                hist_cmds.append(build_history_cmd(s['service'], mac))
        outputs = {}
        if mac_cmds:
            print(f'[INFO] running mac-table commands device={device} count={len(mac_cmds)}')
            try:
                outputs.update(call_run_show(device, mac_cmds))
            except Exception as e:
                print(f'[WARN] mac-table commands failed device={device}: {e}')
        print(f'[INFO] running history commands device={device} count={len(hist_cmds)}')
        hist_outputs = {}
        try:
            # Split to keep each call bounded.
            for i in range(0, len(hist_cmds), 50):
                hist_outputs.update(call_run_show(device, hist_cmds[i:i+50]))
        except Exception as e:
            print(f'[WARN] history commands failed device={device}: {e}')
        vpls_cmd = 'show evpn vpls-pw | no-more'
        try:
            vpls_text = call_run_show(device, [vpls_cmd]).get(vpls_cmd, '')
        except Exception as e:
            vpls_text = f'ERROR: {e}'
        dev_data = {'device': device, 'macs': {}, 'vpls_pw': parse_vpls_pw(vpls_text)}
        for s in services:
            for role, mac in [('pe4_source', s['pe4_mac']), ('rr_source', s['rr_mac'])]:
                cmd = build_mac_cmd(s['service'], mac)
                text = get_output_from_batched(batched, s['service'], mac)
                if text is None:
                    text = outputs.get(cmd, '')
                hcmd = build_history_cmd(s['service'], mac)
                htext = hist_outputs.get(hcmd, '')
                proto = parse_protocol(text)
                entry = {
                    'service_index': s['index'],
                    'service': s['service'],
                    'role': role,
                    'mac': mac,
                    'missing': missing_output(text, mac),
                    'protocol': proto,
                    'protocol_class': protocol_class(proto, text),
                    'interface': parse_interface(text),
                    'sequence': parse_sequence(text),
                    'suppression': parse_suppression(text),
                    'traffic_handling': parse_traffic_handling(text),
                    'history': parse_history(htext),
                    'raw_mac_excerpt': (text or '')[:4000],
                    'raw_history_excerpt': (htext or '')[:4000],
                }
                dev_data['macs'][f"{s['service']}|{role}|{mac}"] = entry
        snap['devices'][dev_key] = dev_data
    path = AUDIT_DIR / f'{label}_snapshot.json'
    write_json(path, snap)
    STATUS[f'{label}_snapshot'] = str(path)
    write_status()
    print(f'[OK] wrote {path}')
    return snap, path

def expected_class(device_key, role):
    # Moved-state expectations.
    if device_key == 'pe4' and role == 'pe4_source':
        return 'pw'
    if device_key == 'rr' and role == 'pe4_source':
        return 'local'
    if device_key == 'pe4' and role == 'rr_source':
        return 'local'
    if device_key == 'rr' and role == 'rr_source':
        return 'pw'
    return 'unknown'

def compare(pre, post):
    issues = []
    def add(category, device_key, entry, detail):
        sample = {
            'category': category,
            'device': post['devices'][device_key]['device'],
            'service': entry.get('service'),
            'role': entry.get('role'),
            'mac': entry.get('mac'),
            'detail': detail,
        }
        issues.append(sample)
    for dev_key, post_dev in post['devices'].items():
        pre_dev = pre['devices'].get(dev_key, {'macs': {}, 'vpls_pw': {}})
        pre_inst = pre_dev.get('vpls_pw', {}).get('installed_count')
        post_inst = post_dev.get('vpls_pw', {}).get('installed_count')
        if pre_inst is not None and post_inst is not None and post_inst < pre_inst:
            issues.append({'category': 'vpls_pw_installed_drop', 'device': post_dev['device'], 'detail': f'{pre_inst}->{post_inst}'})
        if post_dev.get('vpls_pw', {}).get('down_signatures'):
            issues.append({'category': 'vpls_pw_down_signature', 'device': post_dev['device'], 'detail': post_dev['vpls_pw']['down_signatures'][:3]})
        for key, ent in post_dev['macs'].items():
            pre_ent = pre_dev.get('macs', {}).get(key, {})
            if ent.get('missing') or ent.get('sequence') is None:
                add('missing_mac_or_sequence', dev_key, ent, {'missing': ent.get('missing'), 'sequence': ent.get('sequence')})
            exp = expected_class(dev_key, ent.get('role'))
            if exp != 'unknown' and ent.get('protocol_class') != exp:
                add('moved_state_ownership_mismatch', dev_key, ent, {'expected': exp, 'actual': ent.get('protocol_class'), 'protocol': ent.get('protocol'), 'interface': ent.get('interface')})
            if pre_ent.get('sequence') is not None and ent.get('sequence') is not None and ent['sequence'] < pre_ent['sequence']:
                add('sequence_regression_after_ha', dev_key, ent, {'pre': pre_ent.get('sequence'), 'post': ent.get('sequence')})
            hist_reg = ent.get('history', {}).get('sequence_regressions') or []
            if hist_reg:
                add('post_history_sequence_regression', dev_key, ent, hist_reg[:3])
            supp = (ent.get('suppression') or '').lower()
            if supp in {'active', 'mentioned'}:
                add('active_suppression', dev_key, ent, {'suppression': ent.get('suppression')})
            th = ent.get('traffic_handling')
            if th and not re.search(r'(?i)\bforward\b', th) or (th and re.search(r'(?i)non-forward|discard|drop|blackhole|blocked|blocking', th)):
                add('non_forward_traffic_handling', dev_key, ent, {'traffic_handling': th})
            # Unexpected final protocol/interface drift relative to moved-state expectation.
            if pre_ent and pre_ent.get('protocol_class') not in {None, 'unknown'} and ent.get('protocol_class') not in {None, 'unknown'}:
                if ent.get('protocol_class') != exp:
                    add('unexpected_final_protocol_interface_change', dev_key, ent, {'expected': exp, 'pre_protocol_class': pre_ent.get('protocol_class'), 'post_protocol_class': ent.get('protocol_class'), 'pre_interface': pre_ent.get('interface'), 'post_interface': ent.get('interface')})
    counts = {}
    for item in issues:
        counts[item['category']] = counts.get(item['category'], 0) + 1
    report = {
        'verdict': 'PASS' if not issues else 'FAIL',
        'total_inconsistencies': len(issues),
        'counts_by_category': counts,
        'first_10_samples': issues[:10],
        'issues': issues,
    }
    return report

def write_summary(report):
    lines = []
    lines.append('# HA Consistency Audit Summary')
    lines.append('')
    lines.append(f'- HA exit code: {STATUS.get("ha_exit_code")}')
    lines.append(f'- HA result directory: {STATUS.get("ha_result_dir")}')
    lines.append(f'- Audit directory: {AUDIT_DIR}')
    lines.append(f'- Consistency verdict: {report["verdict"]}')
    lines.append(f'- Total inconsistencies: {report["total_inconsistencies"]}')
    lines.append('')
    lines.append('## Counts By Category')
    lines.append('')
    if report['counts_by_category']:
        for k, v in sorted(report['counts_by_category'].items()):
            lines.append(f'- {k}: {v}')
    else:
        lines.append('- none: 0')
    lines.append('')
    lines.append('## First 10 Samples')
    lines.append('')
    if report['first_10_samples']:
        for item in report['first_10_samples']:
            lines.append(f'- {item}')
    else:
        lines.append('- None')
    lines.append('')
    (AUDIT_DIR / 'SUMMARY.md').write_text('\n'.join(lines) + '\n')

pre = post = None
try:
    pre, pre_path = take_snapshot('pre_ha')

    # 3. Run recipe-prescribed moved-state safe HA mode. Do not run bgpd restart.
    cmd = [
        sys.executable, '-u', 'orchestrator.py',
        '--phase', 'ha',
        '--scale', '200',
        '--traffic-strategy', 'modifier',
        '--ha-mode', 'safe_no_bgp',
        '--expected-mac-state', 'moved',
        '--run-tag', 'ha_safe_no_bgp_moved_20260504',
    ]
    print('[INFO] running HA command:', ' '.join(cmd))
    before_dirs = {p.name for p in RESULTS_DIR.glob('RUN_*') if p.is_dir()}
    ha_log = open(AUDIT_DIR / 'ha_orchestrator.log', 'w', buffering=1)
    proc = subprocess.Popen(cmd, cwd=str(TEST_DIR), stdout=ha_log, stderr=subprocess.STDOUT, text=True)
    STATUS['ha_pid'] = proc.pid
    write_status()
    rc = proc.wait()
    ha_log.close()
    STATUS['ha_exit_code'] = rc
    after_dirs = [p for p in RESULTS_DIR.glob('RUN_*') if p.is_dir() and p.name not in before_dirs]
    if after_dirs:
        ha_dir = max(after_dirs, key=lambda p: p.stat().st_mtime)
    else:
        candidates = sorted(RESULTS_DIR.glob('*ha_safe_no_bgp_moved_20260504*'), key=lambda p: p.stat().st_mtime if p.exists() else 0)
        ha_dir = candidates[-1] if candidates else None
    STATUS['ha_result_dir'] = str(ha_dir) if ha_dir else None
    write_status()
    print(f'[INFO] HA exit_code={rc} result_dir={STATUS["ha_result_dir"]}')
finally:
    try:
        post, post_path = take_snapshot('post_ha')
    except Exception:
        traceback.print_exc()
        STATUS['errors'].append('Post-HA snapshot failed')
        write_status()
        raise

try:
    report = compare(pre, post)
    write_json(AUDIT_DIR / 'consistency_report.json', report)
    STATUS['consistency_verdict'] = report['verdict']
    STATUS['inconsistency_counts'] = report['counts_by_category']
    STATUS['first_10_samples'] = report['first_10_samples']
    STATUS['finished_at'] = _dt.datetime.now().isoformat(timespec='seconds')
    write_status()
    write_summary(report)
    print(f'[DONE] verdict={report["verdict"]} inconsistencies={report["total_inconsistencies"]}')
except Exception:
    traceback.print_exc()
    STATUS['errors'].append('Compare/report failed')
    write_status()
    raise
